<?php require_once __DIR__.'/../includes/functions.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->prepare("UPDATE study_groups SET status=IF(status='active','suspended','active') WHERE id=?")->execute([(int)$_POST['id']]);flash('success','Group status updated.');go('groups.php');}$q=db()->query('SELECT g.*,u.name creator,(SELECT COUNT(*) FROM group_members m WHERE m.group_id=g.id) members FROM study_groups g JOIN users u ON u.id=g.creator_id ORDER BY g.created_at DESC');page_start('Study groups',true); ?><div class="card"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Group</th><th>Creator</th><th>Members</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($q as $g): ?><tr><td><?= e($g['name']) ?><div class="small text-secondary"><?= e($g['topic']) ?></div></td><td><?= e($g['creator']) ?></td><td><?= (int)$g['members'] ?></td><td><?= e($g['status']) ?></td><td><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="id" value="<?= $g['id'] ?>"><button class="btn btn-sm btn-outline-secondary">Toggle status</button></form></td></tr><?php endforeach ?></tbody></table></div></div><?php page_end(); ?>
